h, w = 27, 21
special_pos = (16, 20)

def get_edge_status(r, c):
    is_top_row = r == 0
    is_bottom_row = r == h - 1
    is_left_col = c == 0
    is_right_col = c == w - 1

    num_adjacent_edges = sum([is_top_row, is_bottom_row, is_left_col, is_right_col])

    edge_neighbors = 0
    for dr in [-1, 0, 1]:
        for dc in [-1, 0, 1]:
            if dr == 0 and dc == 0:
                continue
            nr, nc = r + dr, c + dc
            if (nr == 0 or nr == h-1) and (nc == 0 or nc == w-1):
                edge_neighbors += 1

    return {
        'row': r, 'col': c,
        'on_edge': num_adjacent_edges > 0,
        'num_edge_neighbors': num_adjacent_edges,
        'corners_nearby': edge_neighbors > 0
    }

all_7_edges = []
for r in range(h):
    for c in range(w):
        if demo_input[r][c] == 7:
            edge_info = get_edge_status(r, c)
            all_7_edges.append((r, c, edge_info))

edge_7s = [(r,c,info) for r, c, info in all_7_edges if info['on_edge']]
print(f"7s on any edge: {len(edge_7s)}")
for r, c, info in edge_7s[:20]:
    print(f"  ({r},{c}): row={info['row']}, col={info['col']}")

stayed_as_7 = [(r,c) for r in range(h) for c in range(w) 
               if demo_input[r][c] == 7 and demo_output[r][c] == 7]
print(f"\n7s that stayed as 7: {stayed_as_7}")

if len(stayed_as_7) <= 5:
    print("Checking which are on edges:")
    for pos in stayed_as_7:
        found = False
        for er, ec, einfo in edge_7s:
            if pos == (er, ec):
                print(f"  {pos} is on edge with info {einfo}")
                found = True
        if not found:
            print(f"  {pos} NOT on edge")
else:
    print(f"There are {len(stayed_as_7)} positions that stayed as 7 - analyzing a few...")

